tool_input.command:
cd /workspaces/semio/semio/engine && python3 -c "
import re
with open('dist/mcp-app.html', 'r') as f:
    content = f.read()
script_match = re.findall(r'<script[^>]*>(.*?)</script>', content, re.DOTALL)
if script_match:
    for s in script_match:
        if len(s) > 100:
            # Find vB definition
            idx = s.find('vB=()=>')  # Arrow function
            if idx == -1:
                idx = s.find('vB=e=>')
            if idx == -1:
                idx = s.find('vB=(')
            if idx == -1:
                # Try another pattern
                m = re.search(r'(const |,)vB=', s)
                if m:
                    idx = m.start()
            if idx >= 0:
                print(s[idx:idx+400])
            else:
                print('vB not found as function')
"

